* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1e1e2f;
  color: #f0f0f0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #2a2a3d;
  border-radius: 24px;
  padding: 32px 24px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 640px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.5px;
  color: #e0e0ff;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

.swatch {
  flex: 1 1 100px;
  min-width: 80px;
  border-radius: 16px;
  padding: 16px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.swatch:hover {
  transform: scale(1.02);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5);
}

.hex {
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: rgba(0, 0, 0, 0.5);
  padding: 4px 8px;
  border-radius: 8px;
  color: #fff;
  text-shadow: 0 1px 2px rgba(0,0,0,0.5);
}

.lock-btn {
  background: rgba(0, 0, 0, 0.5);
  border: none;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1.1rem;
  color: #fff;
  transition: background 0.2s, transform 0.1s;
}

.lock-btn:hover {
  background: rgba(0, 0, 0, 0.7);
}

.lock-btn:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.9);
}

.lock-btn.locked {
  background: #ffb74d;
  color: #1e1e2f;
}

.generate-btn {
  background: #6c5ce7;
  border: none;
  border-radius: 40px;
  padding: 16px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  align-self: center;
  min-width: 200px;
}

.generate-btn:hover {
  background: #7d6ef0;
}

.generate-btn:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.generate-btn:active {
  transform: scale(0.97);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .swatch {
    flex: 1 1 100%;
    flex-direction: row;
    justify-content: space-between;
    padding: 12px 16px;
  }
  .hex {
    font-size: 1rem;
  }
  .lock-btn {
    width: 36px;
    height: 36px;
  }
}

const paletteEl = document.getElementById('palette');
const generateBtn = document.getElementById('generate');

const NUM_SWATCHES = 5;

// State: array of { color, locked }
let swatches = [];

function randomHue() {
  return Math.floor(Math.random() * 360);
}

function hslToHex(h, s, l) {
  s /= 100;
  l /= 100;
  const a = s * Math.min(l, 1 - l);
  const f = (n) => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

function generatePalette() {
  const baseHue = randomHue();
  const harmonyTypes = ['analogous', 'complementary', 'triadic'];
  const type = harmonyTypes[Math.floor(Math.random() * harmonyTypes.length)];

  const hues = [];
  if (type === 'analogous') {
    for (let i = 0; i < NUM_SWATCHES; i++) {
      hues.push((baseHue + i * 30) % 360);
    }
  } else if (type === 'complementary') {
    const comp = (baseHue + 180) % 360;
    for (let i = 0; i < NUM_SWATCHES; i++) {
      hues.push(i % 2 === 0 ? (baseHue + i * 10) % 360 : (comp + i * 10) % 360);
    }
  } else {
    for (let i = 0; i < NUM_SWATCHES; i++) {
      hues.push((baseHue + i * 120) % 360);
    }
  }

  const saturation = 60 + Math.random() * 20;
  const lightness = 50 + Math.random() * 15;

  return hues.map((h) => {
    const s = saturation + (Math.random() * 10 - 5);
    const l = lightness + (Math.random() * 10 - 5);
    return hslToHex(h, Math.max(30, Math.min(90, s)), Math.max(30, Math.min(80, l)));
  });
}

function createSwatchElement(color, locked, index) {
  const div = document.createElement('div');
  div.className = 'swatch';
  div.style.backgroundColor = color;

  const hexSpan = document.createElement('span');
  hexSpan.className = 'hex';
  hexSpan.textContent = color;

  const lockBtn = document.createElement('button');
  lockBtn.className = 'lock-btn' + (locked ? ' locked' : '');
  lockBtn.setAttribute('aria-label', locked ? 'Unlock color' : 'Lock color');
  lockBtn.setAttribute('aria-pressed', locked);
  lockBtn.textContent = locked ? '🔒' : '🔓';
  lockBtn.addEventListener('click', () => {
    swatches[index].locked = !swatches[index].locked;
    render();
  });

  div.appendChild(hexSpan);
  div.appendChild(lockBtn);
  return div;
}

function render() {
  paletteEl.innerHTML = '';
  swatches.forEach((sw, i) => {
    paletteEl.appendChild(createSwatchElement(sw.color, sw.locked, i));
  });
}

function regenerate() {
  const newColors = generatePalette();
  swatches = swatches.map((sw, i) => ({
    color: sw.locked ? sw.color : newColors[i],
    locked: sw.locked,
  }));
  render();
}

function init() {
  const colors = generatePalette();
  swatches = colors.map((color) => ({ color, locked: false }));
  render();
}

generateBtn.addEventListener('click', regenerate);

init();
